render:
const { root, params: p, progress, width, height } = ctx;
const title = root.querySelector('#title');
const t = p.easing === 'smooth' ? progress * progress * (3 - 2 * progress) : progress;
title.textContent = p.text;
Object.assign(title.style, { display: p.visible ? 'block' : 'none', fontFamily: JSON.stringify(p.font), fontSize: p.size + 'px', color: p.color, left: (p.startX + (p.endX - p.startX) * t) * width / 100 + 'px', top: (p.startY + (p.endY - p.startY) * t) * height / 100 + 'px' });
